<script setup>import { onMounted, ref } from 'vue';import { getMyDorm } from '../api/student-dorm';import { useRouter } from 'vue-router';import PageHeader from '../components/PageHeader.vue';const router=useRouter();const dorm=ref(null);const loading=ref(true);const error=ref('');async function load(){loading.value=true;error.value='';try{dorm.value=await getMyDorm()}catch(e){error.value=e?.message||'加载失败'}finally{loading.value=false}}onMounted(load)</script>
<template><section class="page-shell"><PageHeader title="我的宿舍" description="查看当前入住位置与资产套装" /><section class="card"><el-skeleton v-if="loading" :rows="8" animated /><div v-else-if="error" class="state"><p>{{ error }}</p><el-button @click="load">重试</el-button></div><div v-else-if="!dorm" class="state"><el-empty description="当前没有有效入住记录" /><el-button type="primary" @click="router.push('/dorm/scan')">去扫码入住</el-button></div><template v-else><div class="title"><div><h2>{{ dorm.campusName }} · {{ dorm.buildingName }}</h2><p>{{ dorm.roomNo }}室 {{ dorm.bedNo }}床 · {{ dorm.assetSetCode }}</p></div><el-tag type="success">{{ dorm.checkInStatus }}</el-tag></div><el-descriptions :column="1" border><el-descriptions-item label="真实姓名">{{ dorm.realName }}</el-descriptions-item><el-descriptions-item label="学号">{{ dorm.maskedStudentNo }}</el-descriptions-item><el-descriptions-item label="学院 / 专业 / 班级">{{ dorm.collegeName }} / {{ dorm.majorName }} / {{ dorm.className }}</el-descriptions-item><el-descriptions-item label="学籍状态">{{ dorm.studentStatus }}</el-descriptions-item><el-descriptions-item label="联系电话">{{ dorm.maskedContactPhone }}</el-descriptions-item><el-descriptions-item label="资产">{{ dorm.assetNames?.join('、') || '暂无明细' }}</el-descriptions-item><el-descriptions-item label="入住时间">{{ dorm.checkInTime }}</el-descriptions-item></el-descriptions></template></section></section></template>
<style scoped>.card{padding:24px;border:1px solid var(--qh-border);border-radius:var(--qh-radius-lg);background:#fff;box-shadow:var(--qh-shadow-card)}.state{display:grid;justify-items:center;gap:12px;padding:36px}.title{display:flex;justify-content:space-between;gap:14px;margin-bottom:20px}.title h2{margin:0;font-size:22px}.title p{margin:8px 0 0;color:var(--qh-text-secondary)}</style>
